import * as T from 'three';import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
export function preview(part,mesh){let el=document.createElement('section');el.className='kc-preview';el.innerHTML='<header><b></b><button>סגירה</button></header><div></div><p>גוף CAD מחושב מתוך החלק המקורי — כולל קדחים וחיתוכי קצה. גרירה לסיבוב, גלגלת לזום.</p>';el.querySelector('b').textContent=part.mark+' — '+part.name;document.body.append(el);let host=el.querySelector('div'),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(host.clientWidth,host.clientHeight);host.append(renderer.domElement);let scene=new T.Scene;scene.background=new T.Color('#edf3f7');let camera=new T.PerspectiveCamera(35,host.clientWidth/host.clientHeight,.1,1000000);camera.up.set(0,0,1);scene.add(new T.HemisphereLight(0xffffff,0x6d8192,2.4));let light=new T.DirectionalLight(0xffffff,2);light.position.set(-1000,-2000,3000);scene.add(light);let g=new T.BufferGeometry;g.setAttribute('position',new T.Float32BufferAttribute(mesh.vertices,3));g.setIndex(mesh.triangles);g.computeVertexNormals();let mat=new T.MeshStandardMaterial({color:0x478c9f,metalness:.2,roughness:.55,side:T.DoubleSide}),obj=new T.Mesh(g,mat);scene.add(obj);let box=new T.Box3().setFromObject(obj),center=box.getCenter(new T.Vector3),size=box.getSize(new T.Vector3),distance=Math.max(size.length(),1)/2/Math.sin(35*Math.PI/360)*1.2;camera.position.copy(center.clone().add(new T.Vector3(1,-1,.8).normalize().multiplyScalar(distance)));let controls=new OrbitControls(camera,renderer.domElement);controls.zoomSpeed=window.KayanLegacy?.zoomSpeed?.()??3;controls.zoomToCursor=true;controls.target.copy(center);controls.update();const onSpeed=e=>{controls.zoomSpeed=e.detail};window.addEventListener("kayan:zoom-speed",onSpeed);let alive=true;const draw=()=>{if(!alive)return;requestAnimationFrame(draw);controls.update();renderer.render(scene,camera)};draw();let observer=new ResizeObserver(()=>{if(!alive)return;camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();renderer.setSize(host.clientWidth,host.clientHeight)});observer.observe(host);el.querySelector('button').onclick=()=>{alive=false;window.removeEventListener("kayan:zoom-speed",onSpeed);observer.disconnect();controls.dispose();g.dispose();mat.dispose();renderer.dispose();renderer.forceContextLoss();el.remove()};}
